const item = $input.first().json.body || $input.first().json;

const title = item.title || 'Society Notice';
const rawDraft = item.rawDraft || item.content || item.body || '';
const category = item.category || 'GENERAL_NOTICE';
const urgency = item.urgency || 'NORMAL';
const targetAudience = item.targetAudience || 'ALL_RESIDENTS';
const affectedBlocks = item.affectedBlocks || [];
const scheduledDate = item.scheduledDate || 'Immediate';
const contactPerson = item.contactPerson || 'Society Office';

const prompt = `You are the Director of Community Communications & Public Relations for the Mana Residential Community.
Review, polish, and adapt the following society announcement for multi-channel broadcast (WhatsApp, SMS, Notice Board, Push Notification).

Draft Notice:
- Title: ${title}
- Category: ${category} (MAINTENANCE, SAFETY_SECURITY, EVENT_FESTIVAL, BILLING_DUES, GENERAL_NOTICE, RULE_CHANGE)
- Stated Urgency: ${urgency} (LOW, NORMAL, HIGH, URGENT)
- Target Audience: ${targetAudience}
- Affected Blocks: ${JSON.stringify(affectedBlocks)}
- Scheduled Effective Date/Time: ${scheduledDate}
- Escalation Contact: ${contactPerson}
- Raw Message Draft:
"${rawDraft}"

Tone, Legal & Clarity Guidelines:
1. Ensure the tone is polite, professional, and reassuring. If it's a utility disruption (power, water, lift), ensure alternative measures and restore ETA are emphasized.
2. In dues/rules announcements, eliminate accusatory or defamatory language to preserve community harmony.
3. Generate distinct adaptations:
   - whatsappBroadcast: Clean bullet points with bold highlights and emojis.
   - smsSnippet: Under 160 characters, concise and actionable.
   - formalNoticeBoard: Official letterhead circular format suitable for PDF / lobby bulletin.
   - pushNotificationTitle & pushNotificationBody: Brief 1-line lockscreen notification.

Respond ONLY with a valid JSON object matching this schema:
{
  "optimizationScore": number (0 to 100),
  "recommendedUrgency": "LOW" | "NORMAL" | "HIGH" | "URGENT",
  "toneAnalysis": "Assessment of clarity, empathy, and community impact",
  "missingCriticalInfo": string[],
  "channels": {
    "whatsappBroadcast": string,
    "smsSnippet": string,
    "formalNoticeBoard": string,
    "pushNotificationTitle": string,
    "pushNotificationBody": string
  }
}`;

return [{
  json: {
    title,
    category,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  const meta = $('Prepare AI Prompt').first().json;
  parsed = {
    optimizationScore: 75,
    recommendedUrgency: "NORMAL",
    toneAnalysis: "Standard informative circular.",
    missingCriticalInfo: [],
    channels: {
      whatsappBroadcast: "ðŸ“¢ *Mana Community Notice: " + meta.title + "*\n\nPlease review the latest society announcement in the Mana app.",
      smsSnippet: "Mana Community Alert: " + meta.title + ". Please check Mana App for details.",
      formalNoticeBoard: "CIRCULAR\n\nSubject: " + meta.title + "\n\nDear Residents, please be advised of the upcoming society schedule.",
      pushNotificationTitle: meta.title,
      pushNotificationBody: "New society announcement published. Tap to read."
    }
  };
}

const meta = $('Prepare AI Prompt').first().json;

return [{
  json: {
    success: true,
    title: meta.title,
    evaluatedAt: new Date().toISOString(),
    broadcastPlan: parsed
  }
}];
